const TEXTBOOK = {"renal":{"title":"泌尿系统","reference":"《内科护理学》第6版，第五章，书页377—427","diseases":[{"id":"basics","title":"症状与检查","subtitle":"先建立肾脏评估的共同基础","pages":"377—388","stages":{"diagnosis":[{"title":"从机制识别症状","pages":"377—387","items":[{"label":"滤过与重吸收","text":"肾小球负责滤过，肾小管参与重吸收和分泌；肾损伤既可表现为蛋白、红细胞漏出，也可表现为浓缩能力下降。","id":"renal-diagnosis-1100"},{"label":"肾炎性水肿","text":"滤过下降和水钠潴留占重要地位，常先见眼睑、颜面水肿，可伴血压升高。","id":"renal-diagnosis-1101"},{"label":"肾病性水肿","text":"大量尿蛋白丢失、低白蛋白与水钠潴留共同参与；可呈明显凹陷性水肿，严重时有胸腹腔积液。","id":"renal-diagnosis-1102"},{"label":"尿路刺激征","text":"尿频、尿急、尿痛是一组症状，需再结合发热、腰痛、尿液检查定位原因。","id":"renal-diagnosis-1103"},{"label":"尿量与尿色","text":"成人少尿通常指24小时尿量＜400 mL，无尿＜100 mL；红色尿需区分红细胞、血红蛋白、食物或药物影响。","id":"renal-diagnosis-1104"},{"label":"肾性高血压","text":"容量负荷增加及肾素相关机制均可参与；高血压又能进一步损伤肾脏。","id":"renal-diagnosis-1105"}]}],"labs":[{"title":"检查项目及其意义","pages":"379—382","items":[{"label":"尿常规与尿沉渣","text":"分别观察蛋白、潜血、红白细胞及管型；潜血阳性不能直接等同镜下红细胞增多。","id":"renal-labs-1100"},{"label":"蛋白定量","text":"定性用于筛查；24小时定量或规范的尿蛋白比值有助于了解丢失程度及变化。","id":"renal-labs-1101"},{"label":"肾小球功能","text":"肌酐、尿素氮结合eGFR及既往基线解释。尿素氮也受高分解、饮食和消化道出血影响。","id":"renal-labs-1102"},{"label":"肾小管功能","text":"夜尿、尿比重、尿渗透压及相关蛋白检测提供浓缩与重吸收信息；不能只看肌酐。","id":"renal-labs-1103"},{"label":"免疫学线索","text":"补体、ASO及针对性自身抗体用于追查病因；检测阳性需结合临床和病理。","id":"renal-labs-1104"},{"label":"超声与活检","text":"超声了解大小、形态及梗阻；活检回答病理类型、活动程度与治疗判断，不能互相替代。","id":"renal-labs-1105"}]},{"title":"标本与检查配合","pages":"380—382","items":[{"label":"清洁中段尿","text":"先清洁并按检验要求取中段尿，避免触碰容器内面，及时送检；培养尽可能在抗菌治疗前留取，不自行停药。","id":"renal-labs-1106"},{"label":"24小时尿收集","text":"记录起止时间，起点排空后开始收集并包含终点尿；漏收需告知，不以估算补足。","id":"renal-labs-1107"},{"label":"肾穿刺前","text":"核对血压、血常规与凝血情况，了解抗凝等用药；解释配合要求，练习体位和屏气。","id":"renal-labs-1108"},{"label":"肾穿刺后","text":"按术后要求休息并监测血压、脉搏、尿色、腰腹痛；新发肉眼血尿、持续腰痛或循环变化需及时报告。","id":"renal-labs-1109"}]},{"title":"基础护理：尿标本采集","pages":"457—459","book":"基础护理学","items":[{"label":"标本类型","text":"常规标本了解尿液成分；定时尿用于相应定量；培养标本用于病原鉴定及药敏，三者采集要求不同。","id":"renal-labs-5000"},{"label":"身份与项目核对","text":"核对患者身份、检验项目、容器及标签，向患者解释采集起止时间和方法。","id":"renal-labs-5001"},{"label":"定时尿的完整性","text":"起点排空膀胱并弃去该次尿，之后全部收集至终点并包含终点尿；记录总量，按要求混匀和送样。","id":"renal-labs-5002"},{"label":"保存与防污染","text":"按具体项目选择保存条件及是否使用防腐剂，不把同一种防腐剂套用于所有尿检；避免粪便、纸屑或分泌物混入。","id":"renal-labs-5003"},{"label":"导管尿培养","text":"由受训人员按规范消毒采样口后无菌取样，不从集尿袋取培养标本。","id":"renal-labs-5004"}]}],"treatment":[{"title":"把症状处理与病因处理分开","pages":"382—388","items":[{"label":"容量管理","text":"结合尿量、体重、血压、呼吸和肾功能决定限钠、液体管理、利尿或透析，水肿不等于都要补液或都要脱水。","id":"renal-treatment-1100"},{"label":"血压处理","text":"控制容量负荷并配合降压治疗，复测血压和症状，观察体位性不适及药物反应。","id":"renal-treatment-1101"},{"label":"营养处理","text":"蛋白、能量、水钠钾磷需结合病种、肾功能与是否透析调整，避免统一套用一种肾病饮食。","id":"renal-treatment-1102"},{"label":"感染与梗阻","text":"尿路症状要明确病原和尿流情况；感染需合理抗菌，梗阻需评估解除梗阻，单纯止痛不能代替病因治疗。","id":"renal-treatment-1103"}]}],"nursing":[{"title":"评估 → 问题 → 措施 → 评价","pages":"382—387","items":[{"label":"评估容量","text":"询问水肿起始部位、进展、饮水与输液量；测体重、血压，记录尿量和其他出量，检查呼吸及皮肤。","id":"renal-nursing-1100"},{"label":"体液过多","text":"依据水肿、体重增长、呼吸或循环证据提出；措施包括液体记录、限钠配合、用药观察及体位安排。","id":"renal-nursing-1101"},{"label":"皮肤完整性风险","text":"水肿部位避免摩擦与持续受压，保持清洁干燥，定期观察受压处，翻身时避免拖拉。","id":"renal-nursing-1102"},{"label":"用药观察","text":"利尿后同时观察血压、尿量、体重、电解质和脱水表现；不能仅以尿量增多判断处理恰当。","id":"renal-nursing-1103"},{"label":"排尿不适","text":"观察排尿次数、量、疼痛与尿色，提供方便清洁的排尿环境；饮水量仍需服从容量状态。","id":"renal-nursing-1104"},{"label":"评价依据","text":"比较水肿、体重、呼吸、血压、出入量和皮肤变化；把结果写具体，而非笼统写“情况好转”。","id":"renal-nursing-1105"}]},{"title":"护理目标","pages":"377—388","items":[{"label":"容量与皮肤","text":"水肿及呼吸负担减轻，体重和出入量达到个体化管理目标；皮肤保持完整。","id":"renal-nursing-1106"}]},{"title":"基础护理：液体记录与排尿观察","pages":"215—216、326—329、336","book":"基础护理学","items":[{"label":"摄入的范围","text":"饮水、食物含水量、服药用水、输液与输血等均需纳入，按记录要求计量。","id":"renal-nursing-5000"},{"label":"排出的范围","text":"尿液之外，还需记录呕吐、引流、出血和腹透等可测出量；冲洗液需与真正尿量分别核算。","id":"renal-nursing-5001"},{"label":"同一时间段","text":"摄入和排出按相同时间区间记录，及时汇总并与体重、血压及临床表现交叉核对。","id":"renal-nursing-5002"},{"label":"少尿还是潴留","text":"观察膀胱充盈、尿意、下腹不适及导管引流；尿量少可能来自生成减少，也可能来自排出受阻。","id":"renal-nursing-5003"},{"label":"留置导管维护","text":"妥善固定，保持管路无扭折、尿袋低于膀胱且不接触地面；维持密闭系统，按临床指征及规范处理更换。","id":"renal-nursing-5004"}]}]}},{"id":"agn","title":"急性肾小球肾炎","subtitle":"感染后肾炎综合征与容量管理","pages":"389—391","stages":{"diagnosis":[{"title":"病因、表现与鉴别","pages":"389—391","items":[{"label":"机制","text":"链球菌感染后可发生免疫介导的肾小球炎症，并非细菌直接在肾内繁殖。","id":"renal-diagnosis-1200"},{"label":"典型线索","text":"前驱感染后约1—3周出现血尿、蛋白尿、眼睑水肿及血压升高，可有短暂肾功能下降。","id":"renal-diagnosis-1201"},{"label":"疾病谱","text":"轻者仅镜下血尿，重者可发生急性肾损伤；不能因没有明显水肿就排除。","id":"renal-diagnosis-1202"},{"label":"危险变化","text":"气促、端坐呼吸提示容量相关心衰可能；剧烈头痛、呕吐、意识改变需警惕高血压脑病。","id":"renal-diagnosis-1203"}]}],"labs":[{"title":"验证肾炎综合征","pages":"389—390","items":[{"label":"尿液","text":"观察变形红细胞、红细胞管型与蛋白尿；尿量减少要按时间连续记录。","id":"renal-labs-1200"},{"label":"补体","text":"感染后急性肾炎可见C3下降并随恢复回升；持续低补体需要重新考虑病因。","id":"renal-labs-1201"},{"label":"ASO","text":"升高支持近期链球菌感染，不能仅凭ASO确诊肾炎。","id":"renal-labs-1202"},{"label":"肾功能与电解质","text":"肌酐、尿素氮和血钾用于判断受损程度与并发症风险；结合既往值追踪。","id":"renal-labs-1203"}]}],"treatment":[{"title":"以支持和并发症处理为主","pages":"390","items":[{"label":"休息与饮食","text":"急性期减少活动，按水肿、血压、尿量及肾功能安排水钠、钾及蛋白摄入。","id":"renal-treatment-1200"},{"label":"消肿与降压","text":"容量过多时配合利尿，血压控制不足时配合降压，持续评价循环和电解质。","id":"renal-treatment-1201"},{"label":"感染处理","text":"评估有无持续感染灶，抗菌治疗不能替代对免疫性肾损伤及容量问题的处理。","id":"renal-treatment-1202"},{"label":"替代治疗","text":"出现严重急性肾损伤并符合指征时评估短期透析，不能把所有患者都按长期透析管理。","id":"renal-treatment-1203"}]}],"nursing":[{"title":"护理目标","pages":"389—391","items":[{"label":"急性期目标","text":"水肿和血压逐渐稳定，无新发心衰或神经系统异常；能遵循复查与活动安排。","id":"renal-nursing-1205"}]},{"title":"护理闭环","pages":"390—391","items":[{"label":"主要问题","text":"常见体液过多、皮肤损伤风险和活动无耐力；合作处理的并发症包括心衰、高血压脑病、AKI。","id":"renal-nursing-1200"},{"label":"容量观察","text":"每日在可比条件下测体重，准确记出入量；监测血压、呼吸、肺部体征及水肿范围。","id":"renal-nursing-1201"},{"label":"饮食与活动","text":"落实个体化限盐限液，尿少时关注钾；症状改善后逐渐活动，避免劳累。","id":"renal-nursing-1202"},{"label":"预防与随访","text":"做好口腔、皮肤和感染预防，复查尿液、补体、肾功能；不要因肉眼血尿消退就自行结束随访。","id":"renal-nursing-1203"},{"label":"评价","text":"水肿、血压和呼吸负担减轻，皮肤完整，尿量与肾功能趋势改善，并能说明随访要求。","id":"renal-nursing-1204"}]}]}},{"id":"rpgn","title":"急进性肾小球肾炎","subtitle":"识别快速恶化，及时完成病因分型","pages":"391—393","stages":{"diagnosis":[{"title":"识别速度与严重度","pages":"391—392","items":[{"label":"主要特点","text":"肾炎综合征伴肾功能快速下降，少尿或无尿进展明显；病理特征为广泛新月体形成。","id":"renal-diagnosis-1300"},{"label":"免疫分型","text":"可涉及抗肾小球基膜抗体、免疫复合物及少免疫沉积相关类型；分型影响治疗。","id":"renal-diagnosis-1301"},{"label":"优先评估","text":"短期肌酐持续上升、尿量骤减、水肿气促及肺出血线索，需要紧急评估。","id":"renal-diagnosis-1302"}]}],"labs":[{"title":"病因检查与病理","pages":"392","items":[{"label":"趋势","text":"连续复查肌酐、尿素氮、血钾与酸碱状态，并核对尿量记录。","id":"renal-labs-1300"},{"label":"抗体及补体","text":"根据病情检查抗GBM抗体、ANCA、补体等；不同分型的血清学表现不同。","id":"renal-labs-1301"},{"label":"肾活检","text":"帮助确认新月体、活动性与慢性损伤程度，指导治疗和预后判断；做好出血风险评估。","id":"renal-labs-1302"}]}],"treatment":[{"title":"强化治疗与支持","pages":"392—393","items":[{"label":"治疗原则","text":"尽早完成病因判断，专科决定免疫抑制及必要的血浆置换，不能将所有分型套用同一方案。","id":"renal-treatment-1300"},{"label":"并发症处理","text":"同步处理容量过多、高钾、酸中毒和感染，必要时肾脏替代治疗。","id":"renal-treatment-1301"},{"label":"治疗观察","text":"观察免疫抑制相关感染、血糖与血压变化、消化道出血和骨髓抑制等不良反应。","id":"renal-treatment-1302"}]}],"nursing":[{"title":"护理目标","pages":"391—393","items":[{"label":"优先目标","text":"及时发现肾功能及电解质恶化，完成紧急治疗配合，并避免漏识别感染。","id":"renal-nursing-1304"}]},{"title":"监测、保护与支持","pages":"393","items":[{"label":"病情监测","text":"关注少尿、无尿、血钾升高、心律异常、恶心呕吐及气促，及时报告变化。","id":"renal-nursing-1300"},{"label":"感染预防","text":"落实手卫生、口腔皮肤护理和管路无菌维护；免疫抑制时感染表现可不典型。","id":"renal-nursing-1301"},{"label":"心理支持","text":"解释检查治疗目的，了解恐惧与家庭支持，帮助配合持续治疗。","id":"renal-nursing-1302"},{"label":"评价与指导","text":"尿量、肌酐和容量情况趋稳，无新发严重感染；能说明不可自行改药和持续随访的重要性。","id":"renal-nursing-1303"}]}]}},{"id":"cgn","title":"慢性肾小球肾炎","subtitle":"长期蛋白尿、血压与肾功能的连续观察","pages":"394—396","stages":{"diagnosis":[{"title":"病程与进展","pages":"394—396","items":[{"label":"基本表现","text":"蛋白尿、血尿、高血压和水肿可轻重不一，早期可能没有明显不适，病程持续或反复。","id":"renal-diagnosis-1400"},{"label":"病因关系","text":"多数并非由急性肾炎直接迁延而来；免疫损伤、肾小球高压力、高血压和蛋白尿共同影响进展。","id":"renal-diagnosis-1401"},{"label":"加重因素","text":"感染、劳累、容量不足、肾毒性药物及未控制的高血压可诱发恶化。","id":"renal-diagnosis-1402"},{"label":"IgA相关线索","text":"部分IgA肾病在上呼吸道感染同期或短期内出现血尿；与感染后间隔数周的模式作对照，仍需病理确认。","id":"renal-diagnosis-1403"}]}],"labs":[{"title":"不仅看一次肌酐","pages":"394—396","items":[{"label":"尿检","text":"追踪蛋白定量、血尿与尿沉渣，而非只记录蛋白几个加号。","id":"renal-labs-1400"},{"label":"肾功能","text":"结合eGFR及肌酐的长期变化判断进展，必要时追查急性加重因素。","id":"renal-labs-1401"},{"label":"病理与超声","text":"活检帮助明确类型与治疗选择；超声评价形态，晚期可有缩小，但影像不替代病因判断。","id":"renal-labs-1402"}]}],"treatment":[{"title":"延缓进展","pages":"395","items":[{"label":"治疗目标","text":"减少蛋白尿、控制血压、保护剩余肾功能，并纠正感染及其他加重因素。","id":"renal-treatment-1400"},{"label":"降压与降蛋白尿","text":"ACEI或ARB等药物有相应作用，需观察血压、血钾及肌酐；具体选择按病情。","id":"renal-treatment-1401"},{"label":"免疫治疗","text":"依据病理和临床活动性决定，不能把所有慢性肾炎都等同于必须使用激素。","id":"renal-treatment-1402"},{"label":"营养与生活","text":"合理蛋白与能量、按容量状态调节盐水，避免吸烟和自行使用可能损肾的药物。","id":"renal-treatment-1403"}]}],"nursing":[{"title":"护理目标","pages":"394—396","items":[{"label":"长期目标","text":"血压、蛋白尿及营养得到持续管理；患者能识别急性加重信号并按期复查。","id":"renal-nursing-1404"}]},{"title":"长期自我管理","pages":"395—396","items":[{"label":"评估","text":"记录水肿、血压、饮食、尿量、活动耐量及用药依从性，了解家庭支持。","id":"renal-nursing-1400"},{"label":"主要问题","text":"按实际情况选择体液过多、活动无耐力、知识不足等，措施与证据相对应。","id":"renal-nursing-1401"},{"label":"监测与用药","text":"教会规范测血压，按计划复查尿蛋白、肌酐和血钾；发现明显少尿、气促或血压变化及时就诊。","id":"renal-nursing-1402"},{"label":"评价","text":"能执行个体化饮食与用药计划，避免已知加重因素，按期复查并识别需就医的变化。","id":"renal-nursing-1403"}]}]}},{"id":"nephrotic","title":"肾病综合征","subtitle":"蛋白丢失、容量、营养与并发症","pages":"396—401","stages":{"diagnosis":[{"title":"把表现连成机制链","pages":"396—398","items":[{"label":"两项核心条件","text":"成人常用教材口径为尿蛋白＞3.5 g/24 h、血浆白蛋白＜30 g/L；水肿及高脂血症为常见伴随表现。","id":"renal-diagnosis-1500"},{"label":"蛋白尿机制","text":"滤过屏障受损使蛋白漏出，超过小管回收能力；长期大量丢失可加重营养和免疫问题。","id":"renal-diagnosis-1501"},{"label":"水肿机制","text":"低白蛋白降低胶体渗透压，水钠潴留也参与；明显水肿时有效循环容量仍可能不足。","id":"renal-diagnosis-1502"},{"label":"病因分类","text":"区分原发与继发：糖尿病、系统性红斑狼疮等可出现继发性肾病综合征。","id":"renal-diagnosis-1503"},{"label":"重要并发症","text":"感染、血栓栓塞、AKI及心血管问题；突然气促、胸痛、单侧肢体肿痛或少尿要及时评估。","id":"renal-diagnosis-1504"}]}],"labs":[{"title":"定量、病因与安全","pages":"398—400","items":[{"label":"尿蛋白","text":"用规范的定量评估程度与疗效；定性强阳性不代替完整定量。","id":"renal-labs-1500"},{"label":"白蛋白与血脂","text":"结合水肿、饮食和炎症解释，不把白蛋白单值作为唯一营养结论。","id":"renal-labs-1501"},{"label":"肾功能与电解质","text":"肌酐、eGFR及血钾等帮助决定饮食、用药和容量管理。","id":"renal-labs-1502"},{"label":"肾活检","text":"明确病理类型并帮助判断治疗反应与预后；不能仅凭综合征名称推断具体病理。","id":"renal-labs-1503"},{"label":"并发症检查","text":"疑似感染、血栓或免疫治疗不良反应时，按临床线索补充培养、血常规及相关检查。","id":"renal-labs-1504"}]},{"title":"基础护理：尿标本采集","pages":"457—459","book":"基础护理学","items":[{"label":"标本类型","text":"常规标本了解尿液成分；定时尿用于相应定量；培养标本用于病原鉴定及药敏，三者采集要求不同。","id":"renal-labs-5000"},{"label":"身份与项目核对","text":"核对患者身份、检验项目、容器及标签，向患者解释采集起止时间和方法。","id":"renal-labs-5001"},{"label":"定时尿的完整性","text":"起点排空膀胱并弃去该次尿，之后全部收集至终点并包含终点尿；记录总量，按要求混匀和送样。","id":"renal-labs-5002"},{"label":"保存与防污染","text":"按具体项目选择保存条件及是否使用防腐剂，不把同一种防腐剂套用于所有尿检；避免粪便、纸屑或分泌物混入。","id":"renal-labs-5003"},{"label":"导管尿培养","text":"由受训人员按规范消毒采样口后无菌取样，不从集尿袋取培养标本。","id":"renal-labs-5004"}]}],"treatment":[{"title":"治疗目标与用药观察","pages":"398—399","items":[{"label":"一般支持","text":"保证能量，肾功能良好时合理供给正常量优质蛋白；肾功能下降后调整，避免盲目高蛋白补偿尿蛋白。","id":"renal-treatment-1500"},{"label":"消肿","text":"限钠及必要的利尿治疗，观察体重、血压、电解质和有效循环容量；消肿过快可诱发低灌注及血栓风险。","id":"renal-treatment-1501"},{"label":"免疫治疗","text":"按病因与病理选用糖皮质激素及相应免疫抑制剂；疗程及减量由治疗方案决定，不自行停用。","id":"renal-treatment-1502"},{"label":"降低蛋白尿与血脂","text":"按病情配合RAAS相关治疗及降脂；监测血钾、肌酐和相关药物不良反应。","id":"renal-treatment-1503"},{"label":"并发症防治","text":"感染及时评价病原；抗凝需结合血栓和出血风险，不是每位患者都一律使用。","id":"renal-treatment-1504"}]}],"nursing":[{"title":"评估与护理问题","pages":"399—400","items":[{"label":"评估要点","text":"水肿范围、体重、尿量、呼吸及血压；实际进食、既往激素与利尿药使用；感染征象及心理社会支持。","id":"renal-nursing-1500"},{"label":"体液过多","text":"关联低白蛋白、水钠潴留及题干证据；按计划记录出入量、体重和治疗反应。","id":"renal-nursing-1501"},{"label":"营养失调","text":"当摄入不足、持续蛋白丢失等证据支持时提出，记录进食量，配合营养方案并评价耐受。","id":"renal-nursing-1502"},{"label":"感染与皮肤风险","text":"免疫低下、激素治疗及水肿增加风险；分别安排感染监测和皮肤保护，不能只列诊断名称。","id":"renal-nursing-1503"}]},{"title":"护理目标","pages":"396—401","items":[{"label":"容量、营养与安全","text":"水肿减轻，摄入符合营养计划，皮肤完整；未发生感染，或感染得到及时识别和控制。","id":"renal-nursing-1509"}]},{"title":"措施、评价与出院指导","pages":"400—401","items":[{"label":"水肿与活动","text":"明显水肿时休息并保护皮肤；病情允许时适度活动，兼顾血栓预防，避免长期完全不动。","id":"renal-nursing-1504"},{"label":"感染监测","text":"观察体温、呼吸道症状、尿路症状及皮肤红肿；做好口腔、会阴和管路护理。","id":"renal-nursing-1505"},{"label":"用药监测","text":"激素关注血糖、血压、感染及消化道症状；其他免疫抑制药按方案监测血细胞、肝肾功能等。","id":"renal-nursing-1506"},{"label":"效果评价","text":"水肿和体重趋势改善，进食与营养状况改善，皮肤完整，无感染或感染得到及时控制。","id":"renal-nursing-1507"},{"label":"居家管理","text":"按方案服药及减量，记录水肿和尿液变化，定期复查；能说出突发气促、胸痛、少尿等就医信号。","id":"renal-nursing-1508"}]}]}},{"id":"uti","title":"尿路感染","subtitle":"定位感染、规范留样与预防复发","pages":"401—405","stages":{"diagnosis":[{"title":"先定位，再看易感因素","pages":"401—403","items":[{"label":"感染途径","text":"常见为上行感染；尿流不畅、器械操作、糖尿病或免疫抑制等增加风险。","id":"renal-diagnosis-1600"},{"label":"膀胱炎","text":"以尿频、尿急、尿痛为主，一般缺少显著寒战高热和腰部症状。","id":"renal-diagnosis-1601"},{"label":"急性肾盂肾炎","text":"可见发热寒战、腰痛、肾区叩击痛及尿路症状；部分患者尿路刺激征不明显。","id":"renal-diagnosis-1602"},{"label":"无症状菌尿","text":"培养有细菌而无相应症状，不能自动按有症状感染处理；需结合妊娠及拟行操作等情况。","id":"renal-diagnosis-1603"},{"label":"持续高热或加重","text":"腰痛显著加重、寒战、循环异常等需评估肾周感染、梗阻或全身感染。","id":"renal-diagnosis-1604"}]}],"labs":[{"title":"标本质量决定解释","pages":"403","items":[{"label":"尿常规","text":"白细胞尿支持尿路炎症，但不是单项确诊；白细胞管型可提示肾实质受累。","id":"renal-labs-1600"},{"label":"尿培养与药敏","text":"留取新鲜清洁中段尿，尽可能在抗菌治疗前留样；结果需结合症状、采样方式及污染可能。","id":"renal-labs-1601"},{"label":"血液检查","text":"高热或全身感染时关注血常规、炎症、肾功能，必要时按病情留血培养。","id":"renal-labs-1602"},{"label":"影像学","text":"反复感染、结石、梗阻或疗效不佳时评估超声等，查找持续感染的原因。","id":"renal-labs-1603"}]},{"title":"基础护理：尿标本采集","pages":"457—459","book":"基础护理学","items":[{"label":"标本类型","text":"常规标本了解尿液成分；定时尿用于相应定量；培养标本用于病原鉴定及药敏，三者采集要求不同。","id":"renal-labs-5000"},{"label":"身份与项目核对","text":"核对患者身份、检验项目、容器及标签，向患者解释采集起止时间和方法。","id":"renal-labs-5001"},{"label":"定时尿的完整性","text":"起点排空膀胱并弃去该次尿，之后全部收集至终点并包含终点尿；记录总量，按要求混匀和送样。","id":"renal-labs-5002"},{"label":"保存与防污染","text":"按具体项目选择保存条件及是否使用防腐剂，不把同一种防腐剂套用于所有尿检；避免粪便、纸屑或分泌物混入。","id":"renal-labs-5003"},{"label":"导管尿培养","text":"由受训人员按规范消毒采样口后无菌取样，不从集尿袋取培养标本。","id":"renal-labs-5004"}]}],"treatment":[{"title":"抗菌与病因处理","pages":"403—405","items":[{"label":"抗菌治疗","text":"按感染部位、严重度、培养药敏、妊娠及肾功能等选择药物和疗程，不能把短程方案用于所有尿感。","id":"renal-treatment-1600"},{"label":"去除易感因素","text":"识别并处理梗阻、反流及不必要的留置导尿，避免仅重复抗菌而不找原因。","id":"renal-treatment-1601"},{"label":"支持治疗","text":"休息、缓解不适；容量状态允许时合理补充水分并规律排尿。","id":"renal-treatment-1602"},{"label":"疗效复评","text":"评价症状、体温及检查变化，是否复查培养由病情和治疗计划决定；症状消失不等于可擅自停药。","id":"renal-treatment-1603"}]}],"nursing":[{"title":"护理目标","pages":"401—405","items":[{"label":"症状与感染","text":"排尿不适和体温改善，无梗阻或全身感染恶化；患者能正确留样并完成治疗计划。","id":"renal-nursing-1605"}]},{"title":"排尿、体温与导管管理","pages":"402—405","items":[{"label":"排尿障碍","text":"记录尿频尿急尿痛及尿液变化，观察尿量与疼痛部位，提供便于排尿的环境。","id":"renal-nursing-1600"},{"label":"体温过高","text":"监测体温和全身状态，补充营养及允许范围内的液体，保持舒适并观察降温与治疗反应。","id":"renal-nursing-1601"},{"label":"导管管理","text":"只在有指征时留置并每日评估必要性；维持密闭引流，避免扭折，尿袋低于膀胱且不触地。","id":"renal-nursing-1602"},{"label":"个人卫生","text":"指导手卫生、会阴清洁和规律排尿；反复发作时查找诱因，而非仅强调“多喝水”。","id":"renal-nursing-1603"},{"label":"评价与指导","text":"尿路不适和发热缓解，无新发感染恶化；能说明服药、留样、随访以及何时及时就诊。","id":"renal-nursing-1604"}]},{"title":"基础护理：液体记录与排尿观察","pages":"215—216、326—329、336","book":"基础护理学","items":[{"label":"摄入的范围","text":"饮水、食物含水量、服药用水、输液与输血等均需纳入，按记录要求计量。","id":"renal-nursing-5000"},{"label":"排出的范围","text":"尿液之外，还需记录呕吐、引流、出血和腹透等可测出量；冲洗液需与真正尿量分别核算。","id":"renal-nursing-5001"},{"label":"同一时间段","text":"摄入和排出按相同时间区间记录，及时汇总并与体重、血压及临床表现交叉核对。","id":"renal-nursing-5002"},{"label":"少尿还是潴留","text":"观察膀胱充盈、尿意、下腹不适及导管引流；尿量少可能来自生成减少，也可能来自排出受阻。","id":"renal-nursing-5003"},{"label":"留置导管维护","text":"妥善固定，保持管路无扭折、尿袋低于膀胱且不接触地面；维持密闭系统，按临床指征及规范处理更换。","id":"renal-nursing-5004"}]}]}},{"id":"aki","title":"急性肾损伤","subtitle":"病因分类、动态诊断与危险并发症","pages":"405—411","stages":{"diagnosis":[{"title":"病因与诊断条件","pages":"405—408","items":[{"label":"肾前性","text":"循环容量不足、心排血量下降等导致肾灌注不足，持续不纠正可进展为实质损伤。","id":"renal-diagnosis-1700"},{"label":"肾性","text":"缺血或肾毒性物质引起的小管损伤常见，也可来自肾小球、间质或血管病变。","id":"renal-diagnosis-1701"},{"label":"肾后性","text":"结石、肿瘤、前列腺等造成尿路梗阻，需评估梗阻部位和解除方式。","id":"renal-diagnosis-1702"},{"label":"AKI判定","text":"48小时肌酐升高≥26.5 μmol/L，或7天内达基线≥1.5倍，或尿量＜0.5 mL/(kg·h)持续≥6小时，符合任一项需评价AKI。","id":"renal-diagnosis-1703"},{"label":"恢复期特点","text":"尿量可先增加，肌酐下降及小管重吸收恢复较晚；多尿并不等于肾功能已经恢复。","id":"renal-diagnosis-1704"}]}],"labs":[{"title":"追踪趋势并查病因","pages":"408","items":[{"label":"肌酐与尿量","text":"以基线、变化时间和连续记录判断，不能仅按一次绝对值诊断或排除。","id":"renal-labs-1700"},{"label":"电解质和血气","text":"重点关注血钾、酸碱、水钠状态及变化速度；同时结合心电监护与临床表现。","id":"renal-labs-1701"},{"label":"尿液与沉渣","text":"蛋白、红白细胞、上皮细胞及管型帮助查病因；利尿药和输液等可影响尿液指标解释。","id":"renal-labs-1702"},{"label":"超声与进一步检查","text":"先排查梗阻；不明原因肾性AKI必要时进一步病因检查或活检。","id":"renal-labs-1703"}]},{"title":"基础护理：尿标本采集","pages":"457—459","book":"基础护理学","items":[{"label":"标本类型","text":"常规标本了解尿液成分；定时尿用于相应定量；培养标本用于病原鉴定及药敏，三者采集要求不同。","id":"renal-labs-5000"},{"label":"身份与项目核对","text":"核对患者身份、检验项目、容器及标签，向患者解释采集起止时间和方法。","id":"renal-labs-5001"},{"label":"定时尿的完整性","text":"起点排空膀胱并弃去该次尿，之后全部收集至终点并包含终点尿；记录总量，按要求混匀和送样。","id":"renal-labs-5002"},{"label":"保存与防污染","text":"按具体项目选择保存条件及是否使用防腐剂，不把同一种防腐剂套用于所有尿检；避免粪便、纸屑或分泌物混入。","id":"renal-labs-5003"},{"label":"导管尿培养","text":"由受训人员按规范消毒采样口后无菌取样，不从集尿袋取培养标本。","id":"renal-labs-5004"}]}],"treatment":[{"title":"处理可逆原因与紧急问题","pages":"409—410","items":[{"label":"病因处理","text":"低灌注者评估循环并纠正原因；调整可能损肾的药物；肾后性需及时解除梗阻。少尿不能机械大量补液。","id":"renal-treatment-1700"},{"label":"高钾处理","text":"持续心电与血钾监测；钙剂用于心肌保护，胰岛素配合葡萄糖促进钾移入细胞，清除体内钾需其他措施或透析。","id":"renal-treatment-1701"},{"label":"容量与酸碱","text":"按实际出入量、体重、肺部和循环情况制定液体计划，处理容量过多及严重酸中毒。","id":"renal-treatment-1702"},{"label":"肾脏替代治疗","text":"难以控制的高钾、酸中毒、容量过多或尿毒症并发症等需紧急评估，不能等待肌酐达到某个固定数值。","id":"renal-treatment-1703"},{"label":"恢复期","text":"继续观察脱水、低钾及其他电解质丢失，营养和随访持续进行。","id":"renal-treatment-1704"}]}],"nursing":[{"title":"护理目标","pages":"405—411","items":[{"label":"内环境与恢复","text":"容量、电解质和酸碱状态维持稳定；少尿期和多尿期风险均被及时识别，肾功能恢复有连续记录。","id":"renal-nursing-1706"}]},{"title":"分期护理与评价","pages":"409—411","items":[{"label":"少尿期监测","text":"严记出入量，每日体重，监测血压、呼吸、意识及水肿，警惕肺水肿、高钾和酸中毒。","id":"renal-nursing-1700"},{"label":"营养支持","text":"根据分解代谢、肾功能、进食及是否透析安排能量和蛋白，不能靠极端限蛋白来推迟需要的透析。","id":"renal-nursing-1701"},{"label":"降钾用药观察","text":"配合治疗时监测心电、复查血钾；胰岛素相关治疗后持续监测血糖，警惕低血糖。","id":"renal-nursing-1702"},{"label":"感染预防","text":"减少不必要的侵入操作，维护管路，留取标本，观察感染征象和抗感染疗效。","id":"renal-nursing-1703"},{"label":"多尿期护理","text":"记录尿量与体重、血压、电解质，观察口渴、乏力、低灌注或低钾表现，按计划补充丢失。","id":"renal-nursing-1704"},{"label":"效果与随访","text":"容量、电解质和酸碱趋稳，尿量与肌酐趋势改善；出院后复查肾功能，评估是否遗留CKD。","id":"renal-nursing-1705"}]},{"title":"基础护理：液体记录与排尿观察","pages":"215—216、326—329、336","book":"基础护理学","items":[{"label":"摄入的范围","text":"饮水、食物含水量、服药用水、输液与输血等均需纳入，按记录要求计量。","id":"renal-nursing-5000"},{"label":"排出的范围","text":"尿液之外，还需记录呕吐、引流、出血和腹透等可测出量；冲洗液需与真正尿量分别核算。","id":"renal-nursing-5001"},{"label":"同一时间段","text":"摄入和排出按相同时间区间记录，及时汇总并与体重、血压及临床表现交叉核对。","id":"renal-nursing-5002"},{"label":"少尿还是潴留","text":"观察膀胱充盈、尿意、下腹不适及导管引流；尿量少可能来自生成减少，也可能来自排出受阻。","id":"renal-nursing-5003"},{"label":"留置导管维护","text":"妥善固定，保持管路无扭折、尿袋低于膀胱且不接触地面；维持密闭系统，按临床指征及规范处理更换。","id":"renal-nursing-5004"}]}]}},{"id":"ckd","title":"慢性肾脏病与肾衰竭","subtitle":"分期、全身影响与长期管理","pages":"411—419","stages":{"diagnosis":[{"title":"慢性依据与分期","pages":"411—413","items":[{"label":"慢性依据","text":"肾结构或功能异常持续≥3个月；需结合既往尿检、影像、肾功能等，不凭一次肌酐升高判慢性。","id":"renal-diagnosis-1800"},{"label":"GFR分级","text":"G1≥90，G2为60—89，G3a为45—59，G3b为30—44，G4为15—29，G5＜15，单位mL/(min·1.73 m²)。","id":"renal-diagnosis-1801"},{"label":"G1、G2的条件","text":"GFR在正常或轻降范围时仍需有肾损伤证据；评估还要结合病因及白蛋白尿类别。","id":"renal-diagnosis-1802"},{"label":"进展与加重","text":"高血压、蛋白尿和糖尿病等影响进展；感染、低灌注、梗阻或肾毒性药物可造成急性加重。","id":"renal-diagnosis-1803"},{"label":"全身表现","text":"水电解质和酸碱紊乱可伴食欲下降、气促、贫血、出血倾向、瘙痒、骨病与神经症状。","id":"renal-diagnosis-1804"},{"label":"贫血机制","text":"肾脏促红细胞生成素不足是重要原因，也要排查失血、缺铁、营养及炎症等因素。","id":"renal-diagnosis-1805"}]}],"labs":[{"title":"功能、并发症与病因","pages":"414—416","items":[{"label":"肾功能与尿蛋白","text":"跟踪eGFR、肌酐及尿白蛋白/蛋白；不能只看尿素氮或一项绝对值。","id":"renal-labs-1800"},{"label":"贫血检查","text":"血红蛋白、红细胞及铁状态等联合评估，寻找可纠正因素，治疗过程中持续复查。","id":"renal-labs-1801"},{"label":"电解质和骨代谢","text":"观察钾、钠、碳酸氢根、钙、磷及PTH，理解其与心律、酸中毒和骨病的联系。","id":"renal-labs-1802"},{"label":"超声与心血管检查","text":"超声了解肾脏形态；心电与超声心动等帮助评估心律、心功能及相关并发症。","id":"renal-labs-1803"}]},{"title":"基础护理：尿标本采集","pages":"457—459","book":"基础护理学","items":[{"label":"标本类型","text":"常规标本了解尿液成分；定时尿用于相应定量；培养标本用于病原鉴定及药敏，三者采集要求不同。","id":"renal-labs-5000"},{"label":"身份与项目核对","text":"核对患者身份、检验项目、容器及标签，向患者解释采集起止时间和方法。","id":"renal-labs-5001"},{"label":"定时尿的完整性","text":"起点排空膀胱并弃去该次尿，之后全部收集至终点并包含终点尿；记录总量，按要求混匀和送样。","id":"renal-labs-5002"},{"label":"保存与防污染","text":"按具体项目选择保存条件及是否使用防腐剂，不把同一种防腐剂套用于所有尿检；避免粪便、纸屑或分泌物混入。","id":"renal-labs-5003"},{"label":"导管尿培养","text":"由受训人员按规范消毒采样口后无菌取样，不从集尿袋取培养标本。","id":"renal-labs-5004"}]}],"treatment":[{"title":"按病因和阶段管理","pages":"414—415","items":[{"label":"延缓进展","text":"治疗原发病，管理血压、血糖和蛋白尿，纠正低灌注、梗阻、感染等可逆因素。","id":"renal-treatment-1800"},{"label":"营养","text":"非透析与透析阶段需分别制定计划，保证能量并预防营养不良；蛋白和水钠钾磷按状态调整。","id":"renal-treatment-1801"},{"label":"贫血治疗","text":"按检查结果补充造血原料并评估促红细胞生成相关治疗；监测血压、血红蛋白反应及血栓风险。","id":"renal-treatment-1802"},{"label":"钙磷与酸碱","text":"按检查选择磷结合剂及其他相应治疗，结合进餐要求、血钙和血磷观察效果。","id":"renal-treatment-1803"},{"label":"替代治疗时机","text":"综合症状、营养、容量、电解质、肾功能与患者意愿决定；G5不意味着所有人立即开始透析。","id":"renal-treatment-1804"},{"label":"方案范围","text":"透析替代部分排泄功能，肾移植是另一选择；不同方案有不同随访与用药要求。","id":"renal-treatment-1805"}]}],"nursing":[{"title":"护理目标","pages":"411—419","items":[{"label":"维持与自我管理","text":"营养摄入改善，水电解质及酸碱状态稳定，皮肤和通路完好，患者能执行长期管理计划。","id":"renal-nursing-1810"}]},{"title":"五类护理问题与措施","pages":"416—418","items":[{"label":"营养不足","text":"评估进食、消化道症状及体重变化，改善进食环境与口腔状态，记录摄入并复评营养。","id":"renal-nursing-1800"},{"label":"水电解质与酸碱风险","text":"准确记录出入量，观察血压、体重、呼吸、意识及血钾等，发现急变及时报告。","id":"renal-nursing-1801"},{"label":"皮肤损伤风险","text":"水肿和瘙痒时温和清洁、润肤、修剪指甲、避免抓挠；检查受压和出血部位。","id":"renal-nursing-1802"},{"label":"贫血相关护理","text":"评价乏力、心悸、气促及活动耐量；配合治疗，逐渐活动，明显不适时停止并评估。","id":"renal-nursing-1803"},{"label":"感染风险","text":"关注口腔、皮肤、呼吸道及血管通路，保持规范护理；无明显高热也不能忽视感染。","id":"renal-nursing-1804"},{"label":"评价","text":"摄入和营养改善，容量及电解质稳定，皮肤完整、贫血和活动耐量改善，无未识别感染。","id":"renal-nursing-1805"}]},{"title":"居家监测与长期支持","pages":"418—419","items":[{"label":"每日记录","text":"按计划记录体重、血压、尿量与症状，正确执行个体化饮食及用药。","id":"renal-nursing-1806"},{"label":"及时就医","text":"明显气促、胸痛、意识变化、尿量骤减、体重短期快速增长、持续呕吐或感染征象需评估。","id":"renal-nursing-1807"},{"label":"避免自行用药","text":"核对非处方止痛药、中草药及保健品，出现不适先咨询，不随意停减处方药。","id":"renal-nursing-1808"},{"label":"通路与心理支持","text":"计划透析时保护拟建通路的血管，解释治疗选择，评估经济、家庭与社区支持。","id":"renal-nursing-1809"}]},{"title":"基础护理：液体记录与排尿观察","pages":"215—216、326—329、336","book":"基础护理学","items":[{"label":"摄入的范围","text":"饮水、食物含水量、服药用水、输液与输血等均需纳入，按记录要求计量。","id":"renal-nursing-5000"},{"label":"排出的范围","text":"尿液之外，还需记录呕吐、引流、出血和腹透等可测出量；冲洗液需与真正尿量分别核算。","id":"renal-nursing-5001"},{"label":"同一时间段","text":"摄入和排出按相同时间区间记录，及时汇总并与体重、血压及临床表现交叉核对。","id":"renal-nursing-5002"},{"label":"少尿还是潴留","text":"观察膀胱充盈、尿意、下腹不适及导管引流；尿量少可能来自生成减少，也可能来自排出受阻。","id":"renal-nursing-5003"},{"label":"留置导管维护","text":"妥善固定，保持管路无扭折、尿袋低于膀胱且不接触地面；维持密闭系统，按临床指征及规范处理更换。","id":"renal-nursing-5004"}]}]}},{"id":"hd","title":"血液透析","subtitle":"通路保护与透析前、中、后护理","pages":"419—424","stages":{"diagnosis":[{"title":"原理与适用情境","pages":"419—422","items":[{"label":"作用原理","text":"弥散清除溶质，超滤去除多余水分；血透不能完全替代肾脏内分泌和代谢功能。","id":"renal-diagnosis-1900"},{"label":"评估适应情境","text":"AKI或CKD出现难以控制的容量、电解质、酸碱及尿毒症问题时，由专科综合判断。","id":"renal-diagnosis-1901"},{"label":"血管通路","text":"自体动静脉内瘘、移植物及中心静脉导管各有条件；内瘘需成熟后使用，导管需注意感染和固定。","id":"renal-diagnosis-1902"}]}],"labs":[{"title":"透析前后如何评价","pages":"422—424","items":[{"label":"干体重","text":"指无明显容量过多也无脱水时的目标体重，需综合症状、血压、营养和检查动态调整。","id":"renal-labs-1900"},{"label":"基础监测","text":"比较透析前后体重、血压和症状，复查血常规、电解质、肾功能及相应营养、骨代谢指标。","id":"renal-labs-1901"},{"label":"通路评价","text":"观察内瘘震颤、杂音及末梢循环；导管注意红肿、渗血、渗液与发热。","id":"renal-labs-1902"},{"label":"充分性与安全","text":"透析效果需结合处方完成情况、残余肾功能及充分性指标；抗凝时关注出血与相应监测。","id":"renal-labs-1903"}]}],"treatment":[{"title":"处方与并发症处理的关联","pages":"422—423","items":[{"label":"透析处方","text":"超滤目标、时长、频率与抗凝需个体化；透析间期体重增长影响本次脱水安排。","id":"renal-treatment-1900"},{"label":"低血压","text":"识别头晕、冷汗、恶心及血压下降，立即报告并配合调整超滤、体位及循环支持。","id":"renal-treatment-1901"},{"label":"失衡综合征","text":"初次或高度氮质血症者透析后可出现头痛、躁动、抽搐等神经症状，及时报告并按方案处理。","id":"renal-treatment-1902"},{"label":"其他急变","text":"胸痛、呼吸困难、发热、出血或过敏表现需立即评估，不将所有不适归为常见低血压。","id":"renal-treatment-1903"}]}],"nursing":[{"title":"护理目标","pages":"419—424","items":[{"label":"治疗与通路","text":"安全完成计划治疗，容量及症状改善，通路通畅，无持续出血，患者能自查并保护通路。","id":"renal-nursing-1906"}]},{"title":"透析前 → 中 → 后","pages":"422—424","items":[{"label":"透析前","text":"核对治疗计划与体重、血压、出血风险，评估通路，按要求留取血标本，了解本次用药情况。","id":"renal-nursing-1900"},{"label":"透析中","text":"监测生命体征、意识、症状及机器报警；观察管路、穿刺点、凝血与出血，异常立即处理报告。","id":"renal-nursing-1901"},{"label":"透析后","text":"评估血压、体重和头晕，内瘘穿刺点止血时兼顾通畅，导管按规范封管和固定。","id":"renal-nursing-1902"},{"label":"内瘘保护","text":"避免瘘侧测血压、输液抽血、紧袖及受压负重；指导每天检查震颤，出现减弱、消失或肢端发凉疼痛及时就诊。","id":"renal-nursing-1903"},{"label":"饮食与间期管理","text":"按透析方案管理水、盐、钾、磷及蛋白，记录体重、尿量与血压，按期透析。","id":"renal-nursing-1904"},{"label":"评价","text":"治疗完成，容量和症状改善，通路通畅，无持续出血或感染，患者能执行间期管理。","id":"renal-nursing-1905"}]}]}},{"id":"pd","title":"腹膜透析","subtitle":"无菌换液、引流观察与腹膜炎识别","pages":"425—427","stages":{"diagnosis":[{"title":"原理与常见问题","pages":"425—427","items":[{"label":"作用原理","text":"利用腹膜进行水和溶质交换，弥散及渗透相关超滤共同发挥作用。","id":"renal-diagnosis-2000"},{"label":"方式","text":"可采用持续非卧床腹透或自动化腹透等，处方需结合腹膜功能、残余肾功能与生活条件。","id":"renal-diagnosis-2001"},{"label":"主要风险","text":"腹膜炎、出口及隧道感染、引流不畅、漏液、容量异常及营养丢失。","id":"renal-diagnosis-2002"},{"label":"腹膜炎警讯","text":"透出液混浊、腹痛或发热需及时联系透析团队，即使没有明显疼痛也不能忽视混浊透出液。","id":"renal-diagnosis-2003"}]}],"labs":[{"title":"透出液与容量观察","pages":"426—427","items":[{"label":"出入量","text":"准确记录每次灌入量、引流量、留腹时间及尿量；用引流减灌入计算本次净超滤量。","id":"renal-labs-2000"},{"label":"透出液检查","text":"疑似腹膜炎时及时留透出液作细胞计数、分类及培养；记录采样与留腹条件。","id":"renal-labs-2001"},{"label":"感染定位","text":"检查出口处红肿、疼痛、脓性分泌物及隧道压痛，结合全身表现。","id":"renal-labs-2002"},{"label":"其他监测","text":"跟踪体重、血压、血糖、白蛋白及电解质，评价容量和营养状态。","id":"renal-labs-2003"}]}],"treatment":[{"title":"处方与问题处理","pages":"426—427","items":[{"label":"处方原则","text":"透析液浓度、灌入量、交换次数和留腹时间按处方执行，不因超滤少就自行换更高浓度。","id":"renal-treatment-2000"},{"label":"引流不畅","text":"先检查体外管路扭折、夹闭及体位，观察便秘；持续异常报告，不强行冲管或自行加药。","id":"renal-treatment-2001"},{"label":"感染处理","text":"留取标本后及时配合抗感染；药物、给药途径及是否保留导管由透析团队按病情决定。","id":"renal-treatment-2002"},{"label":"营养与液体","text":"腹透存在蛋白和营养丢失，摄入与非透析阶段不同；液体还需考虑尿量、超滤和容量状态。","id":"renal-treatment-2003"}]}],"nursing":[{"title":"护理目标","pages":"425—427","items":[{"label":"换液与容量","text":"换液符合无菌要求，出入量记录可靠，无未识别感染，患者或照护者能演示居家操作及异常联络。","id":"renal-nursing-2006"}]},{"title":"无菌操作与家庭管理","pages":"426—427","items":[{"label":"换液环境","text":"保持换液处清洁，规范手卫生和无菌连接，按培训流程检查透析液及装置。","id":"renal-nursing-2000"},{"label":"液体与记录","text":"透析液按设备要求加温；逐次记录时间、灌入和引出量、颜色和清晰度，异常留样报告。","id":"renal-nursing-2001"},{"label":"出口与导管","text":"保持清洁干燥，妥善固定，避免牵拉、淋湿；观察红肿渗液和隧道疼痛。","id":"renal-nursing-2002"},{"label":"腹痛与混浊","text":"及时报告、按要求留取透出液，结合体温、腹部体征及出入量评估，不仅自行服止痛药。","id":"renal-nursing-2003"},{"label":"家庭培训","text":"患者或照护者应实际演示换液、污染后的应对、记录和联络方式，不能只问“听懂了吗”。","id":"renal-nursing-2004"},{"label":"评价","text":"换液操作规范，记录准确，出口无感染，透出液及容量稳定，能识别并及时报告危险变化。","id":"renal-nursing-2005"}]}]}}],"foundationReference":"《基础护理学》第6版，书页215—216、326—337、457—459","references":[{"title":"KDIGO 2024 CKD 指南","url":"https://kdigo.org/guidelines/ckd-evaluation-and-management/kdigo-2024-ckd-guideline/"},{"title":"CDC 导尿管相关感染预防","url":"https://www.cdc.gov/infection-control/hcp/cauti/summary-of-recommendations.html"},{"title":"ISPD 2022 腹膜炎建议","url":"https://doi.org/10.1177/08968608221080586"},{"title":"KDIGO 2012 AKI 定义与分期","url":"https://kdigo.org/wp-content/uploads/2016/10/KDIGO-2012-AKI-Guideline-English.pdf"},{"title":"UKKA 2023 成人高钾血症指南","url":"https://www.ukkidney.org/sites/default/files/FINAL%20VERSION%20-%20UKKA%20CLINICAL%20PRACTICE%20GUIDELINE%20-%20MANAGEMENT%20OF%20HYPERKALAEMIA%20IN%20ADULTS%20-%20191223.pdf"}]}};
const SUPPLEMENTS = {"renal-diagnosis-1100":[{"kind":"机制","title":"两道功能要分开","text":"肾小球滤出水和小分子 → 肾小管选择性回收并分泌 → 形成终尿。滤过屏障受损与小管回收障碍都可能造成尿蛋白异常，但机制不同。","source":"内科护理学第6版 377—379"},{"kind":"机制","title":"为什么会有管型","text":"蛋白在肾小管内形成基质，包裹细胞或碎屑可成为不同管型；管型有助于判断肾内病变，不能仅凭一个名称完成病因诊断。","source":"内科护理学第6版 377—379"}],"renal-diagnosis-1101":[{"kind":"机制","title":"水钠潴留链","text":"肾小球炎症 → 有效滤过减少 → 水钠排出减少 → 血容量和组织间液增加 → 水肿，并可伴血压升高。","source":"内科护理学第6版 382—383"},{"kind":"易混","title":"与肾病性水肿比较","text":"肾炎性水肿侧重滤过下降和水钠潴留；肾病性水肿常同时存在大量尿蛋白丢失和低白蛋白。实际患者的机制可以重叠。","source":"内科护理学第6版 382—383"}],"renal-diagnosis-1102":[{"kind":"机制","title":"蛋白丢失链","text":"尿白蛋白大量丢失 → 血浆胶体渗透压降低 → 液体更易进入组织间隙；肾内钠潴留及部分患者继发的RAAS激活可进一步加重水肿。","source":"内科护理学第6版 383、397—398"},{"kind":"易混","title":"水肿与有效循环容量","text":"组织间液多，并不保证血管内有效循环容量充足。判断时还要结合血压、脉搏、尿量和治疗反应。","source":"内科护理学第6版 383、397—398"}],"renal-diagnosis-1104":[{"kind":"数值","title":"成人24小时尿量口径","text":"一般成人日尿量常约1000—2000 mL；少尿＜400 mL/24 h，无尿＜100 mL/24 h。均需注明统计时段，结合饮水、出汗及治疗解释。","source":"基础护理学第6版 326—328；内科护理学第6版 386"},{"kind":"易混","title":"少尿与AKI标准","text":"AKI还使用按体重计算的小时尿量与持续时间标准。24小时总量分类、AKI尿量判据、尿潴留是不同概念。","source":"基础护理学第6版 326—328；内科护理学第6版 386"},{"kind":"机制","title":"尿色与潜血","text":"红色尿可能来自红细胞，也可能受血红蛋白、肌红蛋白、食物或药物影响；潜血试纸不等于直接计数尿中红细胞。","source":"基础护理学第6版 326—328；内科护理学第6版 386"}],"renal-diagnosis-1105":[{"kind":"机制","title":"RAAS的顺序","text":"肾灌注下降等刺激肾素释放 → 血管紧张素Ⅰ形成 → 经ACE生成血管紧张素Ⅱ → 血管收缩、醛固酮相关钠潴留 → 血压升高。","source":"内科护理学第6版 379、385—386"},{"kind":"机制","title":"恶性循环","text":"肾损害可促使容量和血压上升；高血压又能损伤肾血管和肾小球，推动肾功能继续下降。","source":"内科护理学第6版 379、385—386"}],"renal-labs-1102":[{"kind":"数值","title":"肌酐的单位换算","text":"1 mg/dL肌酐约等于88.4 μmol/L；0.3 mg/dL约等于26.5 μmol/L。比较前先统一单位，再判断变化幅度和时间。","source":"内科护理学第6版 381；KDIGO 2024 CKD"},{"kind":"易混","title":"肌酐与eGFR","text":"肌酐受肌肉量等影响；eGFR是估算值。肾功能快速变化时，基于稳态假设的eGFR不能当成实时测得的滤过率。","source":"内科护理学第6版 381；KDIGO 2024 CKD"}],"renal-labs-1103":[{"kind":"机制","title":"为什么先见夜尿","text":"浓缩能力减退时，相同溶质的排出需要更多水，可能表现为夜间尿量增加，不能仅用白天少尿来概括肾功能变化。","source":"内科护理学第6版 381"},{"kind":"易混","title":"尿比重与尿渗透压","text":"两者均提供浓缩信息，但尿比重还受葡萄糖、蛋白等较大分子影响；解释时结合尿液成分和采样条件。","source":"内科护理学第6版 381"}],"renal-nursing-1103":[{"kind":"机制","title":"利尿后为何还要查电解质","text":"尿量增加可伴水、钠、钾等丢失；利尿过快还可能降低有效循环容量，因此要同时看血压、体重、电解质及症状。","source":"内科护理学第6版 384"},{"kind":"易混","title":"肌无力不只见于高钾","text":"低钾也可出现乏力和心律问题。不能只凭症状判断钾高低，需结合检验和心电变化。","source":"内科护理学第6版 384"}],"renal-diagnosis-1200":[{"kind":"机制","title":"感染后为什么伤肾","text":"感染相关抗原引发免疫反应 → 免疫复合物相关补体激活和炎症 → 肾小球受损 → 血尿、蛋白尿和滤过减少。它与细菌直接感染肾盂的尿感机制不同。","source":"内科护理学第6版 389"}],"renal-diagnosis-1201":[{"kind":"数值","title":"常用时间线","text":"链球菌感染后约1—3周出现典型肾炎表现，是教材中的常见模式；感染部位不同，潜伏时间可不同。","source":"内科护理学第6版 389—390"},{"kind":"易混","title":"与IgA肾病的时间关系","text":"部分IgA肾病的肉眼血尿可与呼吸道感染同时或相隔1—3天发生；时间线是线索，不能替代病理和病因检查。","source":"内科护理学第6版 389—390"}],"renal-labs-1201":[{"kind":"数值","title":"看动态，不只看一次","text":"典型链球菌感染后肾炎可见C3下降，常在约8周内恢复。持续降低或病程不典型时，应重新评估其他病因。","source":"内科护理学第6版 390"},{"kind":"机制","title":"补体为什么会下降","text":"免疫炎症中补体被激活并消耗，使血清水平下降；恢复趋势可提供病程信息。","source":"内科护理学第6版 390"}],"renal-nursing-1201":[{"kind":"机制","title":"体重为何有价值","text":"短期体重明显上升可反映液体潴留，但必须在相近时间、衣着和称量条件下比较，并结合出入量和呼吸情况。","source":"内科护理学第6版 383—384、390"},{"kind":"易混","title":"评价要包含危险变化","text":"体重下降之外，还要确认没有低血压、脱水或电解质紊乱；出现气促、端坐呼吸或意识异常不能等待日常复测。","source":"内科护理学第6版 383—384、390"}],"renal-diagnosis-1300":[{"kind":"机制","title":"新月体为什么影响滤过","text":"严重炎症损伤肾小球毛细血管壁 → 囊腔内细胞增生及纤维蛋白相关沉积 → 新月体形成并压迫毛细血管丛 → 滤过迅速下降。","source":"内科护理学第6版 391—392"},{"kind":"数值","title":"教材病理描述","text":"教材用超过50%的肾小球出现新月体作为重要病理特征。临床判断仍需结合快速进展的病程、血清学及完整活检报告。","source":"内科护理学第6版 391—392"}],"renal-labs-1301":[{"kind":"易混","title":"三个方向","text":"抗GBM相关型关注抗肾小球基膜抗体；免疫复合物相关型结合补体等；少免疫沉积相关型常与ANCA相关。阳性或阴性都需结合病理解释。","source":"内科护理学第6版 391—392"}],"renal-diagnosis-1401":[{"kind":"机制","title":"残余肾单位的代偿与代价","text":"肾单位减少 → 残余肾单位高灌注、高压力、高滤过 → 长期机械与代谢负担增加 → 硬化和进一步肾单位丢失。","source":"内科护理学第6版 394—395"},{"kind":"易混","title":"慢性肾炎不是一种病理","text":"它涵盖多种病理类型和临床过程，不能由“慢性”二字推出同一免疫治疗方案。","source":"内科护理学第6版 394—395"}],"renal-treatment-1401":[{"kind":"机制","title":"ACEI与ARB如何降低蛋白尿","text":"抑制血管紧张素相关作用可降低肾小球内压力，从而减轻部分患者的蛋白尿；同时影响肾血流动力学与钾排出。","source":"内科护理学第6版 395；KDIGO 2024 CKD"},{"kind":"易混","title":"为什么复查肌酐和钾","text":"治疗获益与低血压、血钾升高及肾功能变化需一起评估；不能只看蛋白尿是否减少。","source":"内科护理学第6版 395；KDIGO 2024 CKD"}],"renal-diagnosis-1500":[{"kind":"数值","title":"成人教材判定口径","text":"尿蛋白＞3.5 g/24 h，血浆白蛋白＜30 g/L；两项均须保留单位。尿蛋白“+++”不能直接当成3.5 g/24 h。","source":"内科护理学第6版 396、398"},{"kind":"易混","title":"综合征与病理类型","text":"这些指标支持肾病综合征的识别，但不能直接判断是微小病变、膜性肾病或其他病理类型。","source":"内科护理学第6版 396、398"}],"renal-diagnosis-1501":[{"kind":"机制","title":"从屏障到蛋白尿","text":"内皮、基膜和足细胞裂隙相关屏障受损 → 蛋白滤出增加 → 超出肾小管回收能力 → 大量蛋白尿。","source":"内科护理学第6版 377、397"},{"kind":"机制","title":"为什么还影响感染和血栓","text":"尿中丢失的不只有白蛋白，还可涉及免疫与凝血调节相关蛋白；再叠加免疫抑制、血液浓缩等因素，增加并发症风险。","source":"内科护理学第6版 377、397"}],"renal-diagnosis-1502":[{"kind":"机制","title":"低白蛋白与液体分布","text":"白蛋白降低 → 血浆胶体渗透压下降 → 液体向组织间隙分布；钠潴留可进一步扩大组织间液量。","source":"内科护理学第6版 383、397—398"},{"kind":"易混","title":"水肿为什么不能直接决定补液","text":"部分患者有效循环容量不足，另一些患者以容量过多为主。是否补液、利尿或其他处理，需结合循环、尿量、肾功能和症状。","source":"内科护理学第6版 383、397—398"},{"kind":"机制","title":"高脂血症的联系","text":"低白蛋白状态相关的肝脏脂蛋白合成增加及脂质分解变化，可促成高脂血症；它不是诊断所需的唯一或充分条件。","source":"内科护理学第6版 383、397—398"}],"renal-diagnosis-1504":[{"kind":"机制","title":"血栓风险不是单一原因","text":"抗凝相关蛋白丢失、促凝变化、血液浓缩、活动减少和治疗因素共同参与；突然胸痛、气促或单侧肢体肿痛要及时评估。","source":"内科护理学第6版 397—398"},{"kind":"易混","title":"为什么不能人人常规抗凝","text":"抗凝获益需与出血风险、白蛋白、病理类型等综合权衡；不能只凭“肾病综合征”五个字套用。","source":"内科护理学第6版 397—398"}],"renal-treatment-1500":[{"kind":"数值","title":"教材中的蛋白摄入示例","text":"肾功能良好的成人，教材常用正常量优质蛋白约0.8—1.0 g/(kg·d)。60 kg对应约48—60 g/日蛋白质，指营养素的量，不是肉类食物重量。","source":"内科护理学第6版 398、400"},{"kind":"条件","title":"这不是全部肾病的统一处方","text":"肾功能下降、透析、急性高分解或营养不良时需重新制定计划，不能机械套用上述示例。","source":"内科护理学第6版 398、400"}],"renal-treatment-1501":[{"kind":"机制","title":"利尿过快的风险链","text":"利尿过快 → 血管内液体减少而组织液回补不及 → 低灌注、血液浓缩 → AKI或血栓风险增加。","source":"内科护理学第6版 398、400"},{"kind":"易混","title":"白蛋白为什么不作普通“营养液”","text":"输注可能暂时改变血管内液体分布，也可能增加循环负荷；持续大量蛋白尿时还会继续丢失。是否使用需按具体病情判断。","source":"内科护理学第6版 398、400"}],"renal-nursing-1502":[{"kind":"机制","title":"营养不足的多条来源","text":"尿蛋白丢失、胃肠道水肿相关摄入和吸收减少、食欲下降等共同作用；护理评估需记录实际进食及耐受。","source":"内科护理学第6版 399—400"},{"kind":"易混","title":"水肿会掩盖消瘦","text":"体重增加可能来自液体而非营养改善，因此要结合摄入、体征、实验室及水肿变化评价。","source":"内科护理学第6版 399—400"}],"renal-nursing-1506":[{"kind":"机制","title":"激素观察项目的依据","text":"免疫抑制增加感染风险，糖代谢影响可使血糖升高，水钠潴留可影响血压与水肿；因此观察不只看尿蛋白。","source":"内科护理学第6版 393、399—401"},{"kind":"易混","title":"为什么不能突然停药","text":"长期糖皮质激素可抑制下丘脑—垂体—肾上腺轴，突然停药还可能引起肾上腺功能不足，并存在疾病复发风险；减量需遵循方案。","source":"内科护理学第6版 393、399—401"}],"renal-diagnosis-1600":[{"kind":"机制","title":"上行感染的路径","text":"尿道口周围细菌 → 尿道 → 膀胱，部分继续上行至肾盂；尿流不畅、反流及器械操作会影响防御。","source":"内科护理学第6版 402；基础护理学第6版 326"},{"kind":"数值","title":"解剖学记忆点","text":"教材中女性尿道约4—5 cm，男性约18—20 cm。女性尿道较短且与会阴部邻近，是易感因素之一，不能据此忽略其他人群风险。","source":"内科护理学第6版 402；基础护理学第6版 326"}],"renal-diagnosis-1601":[{"kind":"易混","title":"定位要点对照","text":"下尿路：尿频、尿急、尿痛较突出；上尿路：更关注寒战高热、腰痛、肾区叩痛及全身表现。老年、免疫低下等患者可不典型。","source":"内科护理学第6版 403"}],"renal-labs-1600":[{"kind":"数值","title":"教材中的白细胞尿口径","text":"尿沉渣白细胞＞5个/高倍视野可提示白细胞尿；需注明显微镜方法及实验室口径。","source":"内科护理学第6版 403"},{"kind":"易混","title":"镜检和培养不是一个单位","text":"白细胞数以个/HPF等表示，细菌培养用CFU/mL等表示。培养阈值受症状、标本来源及人群影响，不把一个数值套给全部患者。","source":"内科护理学第6版 403"}],"renal-nursing-1602":[{"kind":"机制","title":"为什么保持尿袋低于膀胱","text":"利用重力保持顺向引流，避免尿液逆流；同时避免管路扭折及不必要地断开密闭系统。","source":"内科护理学第6版 402；CDC CAUTI"},{"kind":"易混","title":"尿袋满与患者尿多不同","text":"排空后应记录相应时间段内尿量；尿液未流入尿袋还要检查扭折、堵塞及患者实际排尿情况。","source":"内科护理学第6版 402；CDC CAUTI"}],"renal-diagnosis-1700":[{"kind":"机制","title":"从低灌注到小管损伤","text":"低血容量或低心排出量 → 肾血流及滤过减少；持续缺血可引发小管细胞损伤、脱落与管型堵塞，加重滤过下降。","source":"内科护理学第6版 405—407"},{"kind":"易混","title":"少尿不能直接推出缺水","text":"心衰、肾实质损伤或梗阻也可少尿；未经容量评估机械补液可能加重肺水肿。","source":"内科护理学第6版 405—407"}],"renal-diagnosis-1703":[{"kind":"数值","title":"三条判据，满足其一","text":"①48 h内肌酐升高≥0.3 mg/dL（26.5 μmol/L）；②已知或推测7天内升至基线≥1.5倍；③尿量＜0.5 mL/(kg·h)，持续≥6 h。","source":"内科护理学第6版 408；KDIGO 2012 AKI 2.1.1"},{"kind":"例子","title":"把体重和时间算进去","text":"60 kg成人连续6小时共排尿120 mL：120÷60÷6≈0.33 mL/(kg·h)，低于0.5。记录准确且满足持续时间时，可符合AKI尿量判据。","source":"内科护理学第6版 408；KDIGO 2012 AKI 2.1.1"},{"kind":"易混","title":"升高26.5与绝对值26.5","text":"标准中的26.5 μmol/L是“相对基线的增加量”，不是把当前肌酐是否超过26.5作为诊断。","source":"内科护理学第6版 408；KDIGO 2012 AKI 2.1.1"}],"renal-labs-1700":[{"kind":"数值","title":"AKI分期：肌酐部分","text":"1期：基线的1.5—1.9倍或增加≥0.3 mg/dL；2期：2.0—2.9倍；3期：≥3倍，或升至≥4.0 mg/dL，或开始肾脏替代治疗等。须先符合AKI定义；儿童另有条件。","source":"内科护理学第6版 408；KDIGO 2012 AKI 表2"},{"kind":"数值","title":"AKI分期：尿量部分","text":"1期：＜0.5 mL/(kg·h)，持续6—12 h；2期：同一阈值持续≥12 h；3期：＜0.3 mL/(kg·h)持续≥24 h，或无尿≥12 h。","source":"内科护理学第6版 408；KDIGO 2012 AKI 表2"},{"kind":"条件","title":"两类结果不一致怎么办","text":"按达到的较重分期评价，并核对计量、时间及临床背景。不能仅凭24小时平均量推定所有小时都满足某个持续条件。","source":"内科护理学第6版 408；KDIGO 2012 AKI 表2"}],"renal-treatment-1701":[{"kind":"机制","title":"分清三类作用","text":"钙剂：稳定心肌细胞膜，不能直接降低血钾；胰岛素配合葡萄糖：促进钾移入细胞，需防低血糖；透析等清除途径：真正减少体内钾负荷。","source":"内科护理学第6版 409；UKKA 2023 Hyperkalaemia"},{"kind":"数值","title":"严重度与心电监护","text":"UKKA 2023成人口径：血钾≥6.5 mmol/L属重度；≥6.0 mmol/L需紧急心电评估。数值尚未达到重度而已有心电变化或快速恶化，同样不能等待。","source":"内科护理学第6版 409；UKKA 2023 Hyperkalaemia"},{"kind":"易混","title":"暂时移钾不等于清除钾","text":"移入细胞后的血钾仍可能反弹，因此需要复查血钾并处理病因及排钾问题；心电图正常也不能排除高钾危险。","source":"内科护理学第6版 409；UKKA 2023 Hyperkalaemia"}],"renal-diagnosis-1704":[{"kind":"机制","title":"为什么会先多尿","text":"滤过逐步恢复，但小管重吸收与浓缩功能恢复较慢 → 尿中水和溶质丢失增加。","source":"内科护理学第6版 408、410"},{"kind":"易混","title":"多尿后的关注点","text":"除了观察肌酐下降，还需防止容量不足、低钾等丢失性问题；不能看到尿量多就停止全部监测。","source":"内科护理学第6版 408、410"}],"renal-nursing-1702":[{"kind":"机制","title":"为什么持续测血糖","text":"胰岛素促进葡萄糖进入细胞，也会使钾移入细胞。降钾治疗后的低血糖可延迟出现，肾功能不全会影响风险与处理。","source":"内科护理学第6版 409—410；UKKA 2023 Hyperkalaemia"},{"kind":"易混","title":"乏力与意识变化的解释","text":"原病、高钾、低血糖及其他因素都可能引起症状，应结合血糖、血钾、心电和病情变化及时复评。","source":"内科护理学第6版 409—410；UKKA 2023 Hyperkalaemia"}],"renal-diagnosis-1801":[{"kind":"数值","title":"六个区间","text":"G1≥90；G2为60—89；G3a为45—59；G3b为30—44；G4为15—29；G5＜15。单位均为mL/(min·1.73 m²)。","source":"内科护理学第6版 411；KDIGO 2024 CKD 表2"},{"kind":"条件","title":"分级不等于一次诊断","text":"G1、G2需有肾损伤证据才支持CKD；判断慢性还需持续≥3个月等依据。急性变化时不能仅凭一次eGFR给出稳定CKD分期。","source":"内科护理学第6版 411；KDIGO 2024 CKD 表2"}],"renal-labs-1800":[{"kind":"数值","title":"尿白蛋白/肌酐比值ACR","text":"A1＜30 mg/g（＜3 mg/mmol）；A2为30—300 mg/g（3—30 mg/mmol）；A3＞300 mg/g（＞30 mg/mmol）。按KDIGO 2024表格口径学习。","source":"KDIGO 2024 CKD 表3"},{"kind":"易混","title":"ACR与全天总蛋白","text":"ACR反映尿白蛋白与肌酐之比，mg/g不是g/24 h；不能直接把ACR分级与肾病综合征的全天总蛋白阈值互换。","source":"KDIGO 2024 CKD 表3"}],"renal-diagnosis-1805":[{"kind":"机制","title":"肾性贫血链","text":"肾实质受损 → EPO生成减少 → 骨髓红细胞生成刺激不足 → 贫血；缺铁、慢性炎症、失血等可进一步加重。","source":"内科护理学第6版 379、413、417—418"},{"kind":"易混","title":"并非所有贫血都只缺EPO","text":"治疗前仍需评估铁状态、出血及其他贫血原因，不能用“肾性”二字省略病因检查。","source":"内科护理学第6版 379、413、417—418"}],"renal-diagnosis-1804":[{"kind":"机制","title":"肾性骨病的联系","text":"磷排泄减少、活性维生素D减少及钙磷调节异常 → 继发性甲状旁腺功能亢进等变化 → 骨代谢损害；实际血钙和血磷还受阶段与治疗影响。","source":"内科护理学第6版 412—413"},{"kind":"机制","title":"酸中毒与呼吸","text":"肾脏排酸及维持碳酸氢根的能力下降 → 代谢性酸中毒；呼吸加深加快可为代偿表现，但需血气和临床共同判断。","source":"内科护理学第6版 412—413"}],"renal-treatment-1801":[{"kind":"数值","title":"蛋白摄入的适用范围","text":"KDIGO 2024建议成人CKD G3—G5维持约0.8 g/(kg·d)蛋白摄入；此处用于非透析阶段的营养学习，营养不足、代谢不稳定等需调整。","source":"KDIGO 2024 CKD 3.3.1、3.3.2"},{"kind":"数值","title":"钠与食盐别混用","text":"2 g钠约等于5 g氯化钠（食盐）。CKD的限钠建议常用“钠＜2 g/日”表达，不能误写成“食盐＜2 g/日”。需计入加工食品和调味品中的钠。","source":"KDIGO 2024 CKD 3.3.1、3.3.2"},{"kind":"条件","title":"为什么透析后不能照抄","text":"透析会带来蛋白和其他营养丢失，摄入计划与非透析阶段不同；盐丢失性肾病等也不能机械限钠。","source":"KDIGO 2024 CKD 3.3.1、3.3.2"}],"renal-treatment-1804":[{"kind":"机制","title":"为什么不靠一个肌酐值决定","text":"透析决策综合尿毒症症状、容量、电解质和酸碱问题、营养、GFR及患者意愿；同一肌酐值可对应不同肌肉量和临床状态。","source":"KDIGO 2024 CKD 5.4"},{"kind":"数值","title":"准备与开始不是一回事","text":"KDIGO 2024提出成人GFR＜15—20 mL/(min·1.73 m²)或2年KRT风险＞40%时可考虑移植或透析通路规划；规划阈值不是自动开始透析的指令。","source":"KDIGO 2024 CKD 5.4"}],"renal-diagnosis-1900":[{"kind":"机制","title":"弥散：主要解释清除溶质","text":"在浓度差作用下，尿素、钾等溶质跨透析膜移动；速度还受膜、血流、透析液流量等影响。","source":"内科护理学第6版 419—420"},{"kind":"机制","title":"超滤：主要解释除水","text":"透析膜两侧的压力差促使水分跨膜移动。清除溶质和去除水分相关，但不是同一个物理过程。","source":"内科护理学第6版 419—420"},{"kind":"易混","title":"血透与血滤","text":"血液滤过更强调对流清除，血液透析主要利用弥散；血液透析滤过结合两者。","source":"内科护理学第6版 419—420"}],"renal-labs-1900":[{"kind":"机制","title":"干体重怎样理解","text":"它是没有明显液体过多或脱水时的目标体重，需结合血压、症状、体征和营养动态评价，不是永远不变的体重。","source":"内科护理学第6版 422—423"},{"kind":"例子","title":"间期增重的计算","text":"示例：上次透后60.0 kg，本次透前62.4 kg，间期增重2.4 kg，即2.4÷60.0×100%=4%。这只是观察量，不直接等于本次应设定的超滤量。","source":"内科护理学第6版 422—423"}],"renal-treatment-1901":[{"kind":"机制","title":"超滤速度与低血压","text":"血管内液体被去除过快，超过组织液回补与循环代偿能力 → 有效循环容量下降 → 头晕、冷汗、恶心及血压下降。","source":"内科护理学第6版 423"},{"kind":"易混","title":"不能只怪脱水","text":"心律失常、心肌问题、感染或过敏等也可引起低血压，需按当时症状和监测评估。","source":"内科护理学第6版 423"}],"renal-treatment-1902":[{"kind":"机制","title":"为什么出现神经症状","text":"血中尿素等下降过快，脑内相关物质下降相对滞后 → 渗透梯度改变，水向脑组织移动 → 可出现头痛、躁动、抽搐等。","source":"内科护理学第6版 423"},{"kind":"条件","title":"更需关注的情境","text":"初次透析或较重氮质血症患者需特别注意；新出现神经症状还应排查低血糖、卒中等其他急症。","source":"内科护理学第6版 423"}],"renal-nursing-1903":[{"kind":"机制","title":"震颤为什么重要","text":"动脉血经吻合口进入静脉形成高流量通路，触诊震颤及听诊杂音可提供通畅信息；较平常明显减弱或消失需及时评估。","source":"内科护理学第6版 421、424"},{"kind":"易混","title":"止血与通畅要兼顾","text":"压迫止血需要有效，但过度环形压迫可能影响通路血流。保护还包括避免瘘侧测压、抽血、输液及持续受压。","source":"内科护理学第6版 421、424"}],"renal-diagnosis-2000":[{"kind":"机制","title":"溶质如何清除","text":"血液与腹透液间的浓度梯度驱动溶质经腹膜交换；葡萄糖等渗透剂形成的渗透梯度有助于水分进入腹腔。","source":"内科护理学第6版 425"},{"kind":"易混","title":"腹透的超滤与血透不同","text":"腹透除水主要利用透析液渗透梯度，血透除水主要利用跨膜压力差；不能把两者的机制词互换。","source":"内科护理学第6版 425"}],"renal-labs-2000":[{"kind":"数值","title":"净超滤量的公式","text":"本次净超滤量=实际引流量－实际灌入量。示例：灌入2000 mL，引出2300 mL，净超滤为300 mL。","source":"内科护理学第6版 426"},{"kind":"易混","title":"2300 mL不是全部从血中除掉的水","text":"引出量中包含原先灌入的透析液。全天容量还要同时考虑尿量、饮食、其他输液及损失。","source":"内科护理学第6版 426"}],"renal-labs-2001":[{"kind":"数值","title":"诊断需三类证据中的至少两类","text":"①腹痛或透出液混浊等临床表现；②留腹至少2 h后，透出液白细胞＞100/μL且中性粒细胞＞50%；③透出液培养阳性。","source":"ISPD 2022 腹膜炎建议：诊断"},{"kind":"条件","title":"留腹时间必须写上","text":"短留腹、自动化腹透等情况下，细胞计数的解释需结合方案，不能只拿100/μL一个数值排除腹膜炎。","source":"ISPD 2022 腹膜炎建议：诊断"},{"kind":"易混","title":"不能等培养才联系团队","text":"混浊透出液或腹痛需及时报告并留样；培养结果是诊断证据之一，不是开始求助的前提。","source":"ISPD 2022 腹膜炎建议：诊断"}],"renal-nursing-2001":[{"kind":"数值","title":"教材中的温度记忆点","text":"腹透液在输入前按设备规范干加热至接近体温，教材常用约37℃。加温方式与温度监测均需遵循装置要求。","source":"内科护理学第6版 426"},{"kind":"机制","title":"温度与不适","text":"透析液过冷、过热或流速不合适可导致腹部不适；腹痛同时有混浊液或发热时，还要评估感染而非只调温。","source":"内科护理学第6版 426"}],"renal-treatment-2003":[{"kind":"机制","title":"为什么腹透要关注蛋白","text":"蛋白可随透出液丢失，加上食欲下降等因素增加营养不足风险；不能沿用未透析时的极低蛋白思路。","source":"内科护理学第6版 426"},{"kind":"易混","title":"水分计划需计算哪些出量","text":"除尿量外还要计入腹透净超滤及其他损失；前一天尿量加固定数值只能是特定情境的估算，不能当成所有人的每日饮水处方。","source":"内科护理学第6版 426"}]};
